import { Component } from '@angular/core';
import { ReportsService } from '../reports.service';
import { Subscription } from 'rxjs';
import { generalLedger } from 'src/app/core/interfaces/reports.interface';

@Component({
    selector: 'app-general-ledger',
    templateUrl: './general-ledger.component.html',
    styleUrl: './general-ledger.component.scss',
})
export class GeneralLedgerComponent {
    data;
    subscriptions = new Subscription();
    totals;
    account;
    show_dollar = true;

    accounts_details: generalLedger[] = [];

    constructor(private reportsService: ReportsService) {}
    ngOnInit() {
        this.subscriptions.add(
            this.reportsService.generalLedgerTotals.subscribe((data) => {
                this.totals = {
                    debit: 0,
                    credit: 0,
                    balance: 0,
                    debit_lbp: 0,
                    credit_lbp: 0,
                    balance_lbp: 0,
                };
                this.data = data;
                for (let i = 0; i < this.data.length; i++) {
                    this.totals.debit += parseFloat(data[i].total_debit);
                    this.totals.credit += parseFloat(data[i].total_credit);
                    this.totals.balance += parseFloat(data[i].balance);
                    this.totals.debit_lbp += parseFloat(
                        data[i].total_debit_lbp
                    );
                    this.totals.credit_lbp += parseFloat(
                        data[i].total_credit_lbp
                    );
                    this.totals.balance_lbp += parseFloat(data[i].balance_lbp);
                }
            })
        );
        this.subscriptions.add(
            this.reportsService.generalLedger.subscribe((data) => {
                this.accounts_details = data;
            })
        );
    }
    ngOnDestroy() {
        this.subscriptions.unsubscribe();
    }

    getAccountDetails(account) {
        return this.accounts_details.filter(
            (acc) => acc.account_number === account.account_number
        );
    }
    getBalance(account, currency = 'USD') {
        if (currency === 'USD')
            return parseFloat(account.debit) - parseFloat(account.credit);
        else {
            return (
                parseFloat(account.debit_lbp) - parseFloat(account.credit_lbp)
            );
        }
    }
    public toFloat(value: string): number {
        return parseFloat(value);
    }
}
