import { Component, inject } from '@angular/core';
import { ReportsService } from '../reports.service';
import { LinksService } from 'src/app/components/links-component/links.service';

@Component({
    selector: 'revenue',
    templateUrl: './revenue.component.html',
    styleUrl: './revenue.component.scss',
})
export class RevenueComponent {
    readonly reportsService = inject(ReportsService);
    readonly linksService = inject(LinksService);

    constructor() {
        this.getData();
    }

    getData() {
        this.reportsService.getRevenue();
        this.reportsService.getReturns();
    }

    links = this.linksService.links;
    loadingLinks = this.linksService.loadingLinks;
    selectedLinkId = this.reportsService.selectedLinkId;

    // revenue
    revenue = this.reportsService.revenue;
    loadingRevenue = this.reportsService.loadingRevenue;

    // returns
    returns = this.reportsService.returns;
    loadingReturns = this.reportsService.loadingReturns;
}
