import {
    Component,
    inject,
    OnInit,
    provideExperimentalCheckNoChangesForDebug,
} from '@angular/core';
import { ProductReportService } from './product-report.service';
import { Products } from 'src/app/core/interfaces/stock.interface';
import { DateService } from 'src/app/_services/date.service';
import { FormBuilder, Validators } from '@angular/forms';
import { Message } from 'primeng/api';

@Component({
    selector: 'app-product-report',
    templateUrl: './product-report.component.html',
    styleUrl: './product-report.component.scss',
})
export class ProductReportComponent implements OnInit {
    readonly productReportService = inject(ProductReportService);
    readonly dateService = inject(DateService);
    readonly fb = inject(FormBuilder);

    message!: Message[];
    ngOnInit(): void {
        this.message = [{ severity: 'info', detail: 'Select an item first!' }];
    }

    dialogVisible = false;

    startDate = this.productReportService.startDate;
    endDate = this.productReportService.endDate;
    selectedProduct = this.productReportService.selectedProduct;
    productHistory = this.productReportService.productHistory;
    productHistoryLoading = this.productReportService.productHistoryLoading;

    productHistoryTotals = this.productReportService.productHistoryTotals;

    assignSelectedProduct(product) {
        this.productReportService.productHistory.set([]);
        this.productReportService.selectedProduct.set(product);
        this.search();
    }

    submitted = false;
    search() {
        this.submitted = true;
        if (this.selectedProduct()) {
            this.productReportService.searchProductHistory();
        }
    }

    // get severity
    getSeverity(type): any {
        switch (type) {
            case 'Sale':
                return 'primary';

            case 'Purchase':
                return 'success';

            case 'Return':
                return 'warning';

            case 'DELETE':
                return 'danger';

            case 'ADD':
                return 'contrast';

            case 'REMOVE':
                return 'danger';

            default:
                return 'contrast';
        }
    }
}
