import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { ReportsHomeComponent } from './reports-home/reports-home.component';
import { TopSalesComponent } from './top-sales/top-sales.component';
import { RevenueComponent } from './revenue/revenue.component';
import { InventoryStatusComponent } from './inventory-status/inventory-status.component';
import { TrialBalanceComponent } from './trial-balance/trial-balance.component';
import { GeneralLedgerComponent } from './general-ledger/general-ledger.component';
import { StatementsComponent } from './statements/statements.component';
import { BalanceSheetComponent } from './balance-sheet/balance-sheet.component';
import { GeneralStatementsComponent } from './general-statements/general-statements.component';
import { AuxiliaryStatementsComponent } from './auxiliary-statements/auxiliary-statements.component';
import { ProductReportComponent } from './product-report/product-report.component';
import { CustomersTotalsComponent } from './customers-totals/customers-totals.component';

const routes: Routes = [
    {
        path: '',
        component: ReportsHomeComponent,
        children: [
            {
                path: 'revenue',
                data: {
                    breadcrumb: 'Revenue',
                },
                component: RevenueComponent,
            },
            {
                path: 'product-report',
                data: {
                    breadcrumb: 'Product Report',
                },
                component: ProductReportComponent,
            },
            {
                path: 'top-sales',
                data: {
                    breadcrumb: 'Top Sales',
                },
                component: TopSalesComponent,
            },
            {
                path: 'customers-totals',
                data: {
                    breadcrumb: 'Customers Totals',
                },
                component: CustomersTotalsComponent,
            },
            {
                path: 'inventory-status',
                data: {
                    breadcrumb: 'Inventory Status',
                },
                component: InventoryStatusComponent,
            },
            {
                path: 'trial-balance',
                data: {
                    breadcrumb: 'Trial Balance',
                },
                component: TrialBalanceComponent,
            },
            {
                path: 'general-ledger',
                data: {
                    breadcrumb: 'General Ledger',
                },
                component: GeneralLedgerComponent,
            },
            {
                path: 'account-ledger',
                data: {
                    breadcrumb: 'Account Ledger',
                },
                component: StatementsComponent,
            },
            {
                path: 'balance-sheet',
                data: {
                    breadcrumb: 'Balance Sheet',
                },
                component: BalanceSheetComponent,
            },
            {
                path: 'statement-of-accounts',
                data: {
                    breadcrumb: 'General Ledger Statements',
                },
                component: GeneralStatementsComponent,
            },
            {
                path: 'auxiliary-statements',
                data: {
                    breadcrumb: 'Auxiliary Statements',
                },
                component: AuxiliaryStatementsComponent,
            },
            { path: '**', redirectTo: '/reports/revenue' },
        ],
    },
];

@NgModule({
    imports: [RouterModule.forChild(routes)],
    exports: [RouterModule],
})
export class ReportsRoutingModule {}
