import { Component, OnDestroy, OnInit } from '@angular/core';
import { ReportsService } from '../reports.service';
import { Subscription } from 'rxjs';
import { DateService } from 'src/app/_services/date.service';

@Component({
    selector: 'report-dates',
    templateUrl: './report-dates.component.html',
    styleUrl: './report-dates.component.scss',
})
export class ReportDatesComponent implements OnInit, OnDestroy {
    constructor(
        private reportsService: ReportsService,
        private dateService: DateService
    ) {}

    subscriptions: Subscription = new Subscription();

    startDate;
    endDate;

    ngOnInit(): void {
        this.subscriptions.add(
            this.reportsService.startDate.subscribe((res) => {
                this.startDate = res;
            })
        );
        this.subscriptions.add(
            this.reportsService.endDate.subscribe((res) => {
                this.endDate = res;
            })
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    startDateChanged() {
        this.reportsService.startDate.next(
            this.dateService.formatDate(this.startDate)
        );
        this.reportsService.init_reports();
    }

    endDateChanged() {
        this.reportsService.endDate.next(
            this.dateService.formatDate(this.endDate)
        );
        this.reportsService.init_reports();
    }

    // select today
    selectToday() {
        this.reportsService.startDate.next(this.dateService.getCurrentDate());
        this.reportsService.endDate.next(this.dateService.getCurrentDate());

        this.reportsService.init_reports();
    }

    // this month
    selectThisMonth() {
        this.reportsService.startDate.next(
            this.dateService.getStartOfCurrentMonth()
        );
        this.reportsService.endDate.next(
            this.dateService.getEndOfCurrentMonth()
        );

        this.reportsService.init_reports();
    }

    // this year
    selectThisYear() {
        this.reportsService.startDate.next(this.dateService.getStartOfYear());
        this.reportsService.endDate.next(this.dateService.getEndOfYear());

        this.reportsService.init_reports();
    }
}
