import { Component, OnDestroy, OnInit } from '@angular/core';
import { ReportsService } from '../reports.service';
import { Subscription } from 'rxjs';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';

@Component({
    selector: 'top-sales',
    templateUrl: './top-sales.component.html',
    styleUrl: './top-sales.component.scss',
})
export class TopSalesComponent implements OnInit, OnDestroy {
    constructor(
        private reportsService: ReportsService,
        private auxiliaryService: AuxiliaryService
    ) {}

    subscriptions: Subscription = new Subscription();

    topCategories;
    topItems;
    categoryOptions;
    categoryData;
    itemsData;
    itemsOptions;
    aspectRatio: number = 1.3;

    customers: AuxiliaryAccount[];

    customerChange(customer_id) {
        this.reportsService.getTopItems(customer_id);
    }

    ngOnInit(): void {
        this.subscriptions.add(
            this.auxiliaryService.customers.subscribe((res) => {
                this.customers = res;
            })
        );
        const documentStyle = getComputedStyle(document.documentElement);
        const textColor = documentStyle.getPropertyValue('--text-color');
        const textColorSecondary = documentStyle.getPropertyValue(
            '--text-color-secondary'
        );
        const surfaceBorder =
            documentStyle.getPropertyValue('--surface-border');
        const secondaryColor = documentStyle.getPropertyValue('--surface-400');
        const successColor = documentStyle.getPropertyValue('--green-600');
        const primaryColor = documentStyle.getPropertyValue('--primary');

        this.subscriptions.add(
            this.reportsService.topCategories.subscribe((res) => {
                this.topCategories = res;

                let labels = this.topCategories.map(
                    (record) => record.category_name
                );
                let categoryData = this.topCategories.map(
                    (record) => record.count
                );

                let yMaxAxis;
                if (categoryData.length > 0) {
                    yMaxAxis = Math.max(...categoryData);
                }
                this.categoryData = {
                    labels: labels,
                    datasets: [
                        {
                            label: 'Categories Sold',
                            data: categoryData,
                        },
                    ],
                };
                // categoryOptions
                this.categoryOptions = {
                    cutout: '60%',
                    aspectRatio: this.aspectRatio,
                };
            })
        );

        this.subscriptions.add(
            this.reportsService.topItems.subscribe((res) => {
                this.topItems = res;

                let labels = this.topItems.map((record) => record.item_name);
                let itemsData = this.topItems.map((record) => record.count);

                let yMaxAxis;
                if (itemsData.length > 0) {
                    yMaxAxis = Math.max(...itemsData);
                }
                this.itemsData = {
                    labels: labels,
                    datasets: [
                        {
                            label: 'Top Items Sold',
                            data: itemsData,
                        },
                    ],
                };
                // itemsOptions
                this.itemsOptions = {
                    aspectRatio: this.aspectRatio,
                };
            })
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }
}
