import { Component, inject } from '@angular/core';
import { ReportsService } from '../reports.service';
import { Subscription } from 'rxjs';
import { FormBuilder, Validators } from '@angular/forms';
import { DateService } from 'src/app/_services/date.service';
import { DecimalService } from 'src/app/_services/decimal.service';
import { PrintService } from 'src/app/print.service';

@Component({
    selector: 'app-trial-balance',
    templateUrl: './trial-balance.component.html',
    styleUrl: './trial-balance.component.scss',
})
export class TrialBalanceComponent {
    constructor(
        private reportsService: ReportsService,
        private fb: FormBuilder,
        private dateService: DateService
    ) {}

    readonly decimalService = inject(DecimalService);
    readonly printService = inject(PrintService);

    subscriptions = new Subscription();
    show_dollar = true;
    data;
    details = [];
    totals;
    expandableRows = [];

    trialBalanceLoading: boolean;

    currencyOptions;
    currencyValue;

    trialBalanceForm = this.fb.group({
        startDate: [
            this.dateService.getStartOfCurrentMonth(),
            Validators.required,
        ],
        endDate: [this.dateService.getCurrentDate(), Validators.required],
        showZero: [false],
        showAuxiliary: [false],
        onlyAuxiliary: [false],
    });

    get showAuxiliary() {
        return this.trialBalanceForm.get('showAuxiliary');
    }

    ngOnInit(): void {
        this.subscriptions.add(
            this.reportsService.currencyOptions.subscribe((res) => {
                this.currencyOptions = res;
            })
        );
        this.subscriptions.add(
            this.reportsService.currencyValue.subscribe((res) => {
                this.currencyValue = res;
            })
        );
        this.subscriptions.add(
            this.reportsService.trialBalanceLoading.subscribe((res) => {
                this.trialBalanceLoading = res;
            })
        );

        this.subscriptions.add(
            this.reportsService.trialBalance.subscribe((data) => {
                this.data = data;
                this.totals = {
                    initial_debit: 0,
                    initial_credit: 0,
                    period_debit: 0,
                    period_credit: 0,
                    end_debit: 0,
                    end_credit: 0,
                    initial_debit_lbp: 0,
                    initial_credit_lbp: 0,
                    period_debit_lbp: 0,
                    period_credit_lbp: 0,
                    end_debit_lbp: 0,
                    end_credit_lbp: 0,
                };
                for (let i = 0; i < data.length; i++) {
                    this.totals.initial_debit = this.decimalService.add(
                        this.totals.initial_debit,
                        data[i].initial_debit
                    );

                    this.totals.initial_credit = this.decimalService.add(
                        this.totals.initial_credit,
                        data[i].initial_credit
                    );

                    this.totals.period_debit = this.decimalService.add(
                        this.totals.period_debit,
                        data[i].period_debit
                    );

                    this.totals.period_credit = this.decimalService.add(
                        this.totals.period_credit,
                        data[i].period_credit
                    );

                    this.totals.end_debit = this.decimalService.add(
                        this.totals.end_debit,
                        data[i].end_debit
                    );

                    this.totals.end_credit = this.decimalService.add(
                        this.totals.end_credit,
                        data[i].end_credit
                    );

                    this.totals.initial_debit_lbp = this.decimalService.add(
                        this.totals.initial_debit_lbp,
                        data[i].initial_debit_lbp
                    );

                    this.totals.initial_credit_lbp = this.decimalService.add(
                        this.totals.initial_credit_lbp,
                        data[i].initial_credit_lbp
                    );

                    this.totals.period_debit_lbp = this.decimalService.add(
                        this.totals.period_debit_lbp,
                        data[i].period_debit_lbp
                    );

                    this.totals.period_credit_lbp += parseFloat(
                        data[i].period_credit_lbp
                    );
                    this.totals.period_credit_lbp = this.decimalService.add(
                        this.totals.period_credit_lbp,
                        data[i].period_credit_lbp
                    );

                    this.totals.end_debit_lbp = this.decimalService.add(
                        this.totals.end_debit_lbp,
                        data[i].end_debit_lbp
                    );

                    this.totals.end_credit_lbp = this.decimalService.add(
                        this.totals.end_credit_lbp,
                        data[i].end_credit_lbp
                    );
                }
            })
        );
        this.subscriptions.add(
            this.reportsService.AuxilaryDetails.subscribe((data) => {
                this.details = data;
                data.forEach((item) => {
                    this.expandableRows[item.account_id_fk] = true;
                });
            })
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    getAccountDetails(account: any) {
        return this.details.filter((item) => {
            return item.account_id_fk === account.id;
        });
    }

    changeCurrency(event) {
        this.reportsService.currencyValue.next(event.value);
    }

    submitForm() {
        if (this.trialBalanceForm.valid) {
            this.reportsService.trialBalance.next([]);
            this.reportsService.AuxilaryDetails.next([]);

            this.trialBalanceForm.patchValue({
                startDate: this.dateService.formatDate(
                    this.trialBalanceForm.value.startDate
                ),
                endDate: this.dateService.formatDate(
                    this.trialBalanceForm.value.endDate
                ),
            });

            this.reportsService.getTrialBalance(this.trialBalanceForm.value);
            if (this.trialBalanceForm.value.showAuxiliary) {
                this.reportsService.getAuxilaryDetails(
                    this.trialBalanceForm.value
                );
            }
        }
    }

    printTrialBalance() {
        let dataToPrint = [
            this.data,
            this.currencyValue,
            this.trialBalanceForm.value.startDate,
            this.trialBalanceForm.value.endDate,
            this.totals,
        ];

        console.log(dataToPrint);

        this.printService.printTrialBalance(dataToPrint);
    }
}
