import { Component, computed, inject } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { ReportsService } from '../reports.service';
import { DateService } from 'src/app/_services/date.service';
import {
    BalanceSheetGroup,
    BalanceSheetLine,
} from 'src/app/core/interfaces/balance-sheet.interface';

@Component({
    selector: 'app-balance-sheet',
    templateUrl: './balance-sheet.component.html',
    styleUrl: './balance-sheet.component.scss',
})
export class BalanceSheetComponent {
    private readonly fb = inject(FormBuilder);
    readonly reportsService = inject(ReportsService);
    readonly dateService = inject(DateService);

    readonly sheet = this.reportsService.balanceSheet;
    readonly loading = this.reportsService.loadingBalanceSheet;

    balanceSheetForm = this.fb.group({
        asOf: [this.dateService.getCurrentDate(), Validators.required],
        showZero: [false],
    });

    /** the date the displayed figures belong to, not the one in the picker */
    readonly displayedDate = computed(() => this.sheet()?.as_of ?? null);

    readonly assetGroups = computed(() =>
        this.groupLines(this.sheet()?.assets ?? []),
    );
    readonly liabilityGroups = computed(() =>
        this.groupLines(this.sheet()?.liabilities ?? []),
    );
    readonly equityGroups = computed(() =>
        this.groupLines(this.sheet()?.equity ?? []),
    );

    /** accounts whose class had to be inferred, worth flagging to the user */
    readonly derivedAccounts = computed(() => {
        const sheet = this.sheet();
        if (!sheet) return [];
        return [...sheet.assets, ...sheet.liabilities, ...sheet.equity].filter(
            (line) => line.type_derived,
        );
    });

    ngOnInit(): void {
        this.submitForm();
    }

    /**
     * Collapses the flat account list into chart-of-accounts sub-categories,
     * keeping the account_number order the server sent.
     */
    private groupLines(lines: BalanceSheetLine[]): BalanceSheetGroup[] {
        const groups = new Map<string, BalanceSheetGroup>();

        for (const line of lines) {
            const key = line.sub_category_number || 'other';
            let group = groups.get(key);

            if (!group) {
                group = {
                    key,
                    label: line.sub_category_name || 'Other Accounts',
                    category_name: line.category_name,
                    lines: [],
                    subtotal: 0,
                    redundant_header: false,
                };
                groups.set(key, group);
            }

            group.lines.push(line);
            group.subtotal = this.round(group.subtotal + Number(line.amount));
        }

        for (const group of groups.values()) {
            // a sub-category holding one identically named account (the net
            // result line, for one) would otherwise print its title twice
            group.redundant_header =
                group.lines.length === 1 &&
                group.lines[0].english_name === group.label;
        }

        return [...groups.values()];
    }

    private round(value: number): number {
        return Math.round(value * 100) / 100;
    }

    submitForm() {
        if (this.balanceSheetForm.invalid) return;

        const { asOf, showZero } = this.balanceSheetForm.value;
        this.reportsService.getBalanceSheet(asOf, showZero);
    }

    /**
     * Prints the statement itself rather than the whole screen: the body class
     * drives the print rules in styles.scss that strip the app chrome.
     */
    printBalanceSheet() {
        document.body.classList.add('printing-report');
        window.addEventListener(
            'afterprint',
            () => document.body.classList.remove('printing-report'),
            { once: true },
        );
        window.print();
    }
}
