import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { computed, inject, Injectable, signal } from '@angular/core';
import { ApiService } from 'src/app/_services/api.service';
import { DateService } from 'src/app/_services/date.service';
import { DecimalService } from 'src/app/_services/decimal.service';
import { NotificationsService } from 'src/app/_services/notifications.service';
import { Products } from 'src/app/core/interfaces/stock.interface';

@Injectable({
    providedIn: 'root',
})
export class ProductReportService {
    readonly dateService = inject(DateService);
    readonly http = inject(HttpClient);
    readonly api = inject(ApiService);
    readonly notificationService = inject(NotificationsService);
    readonly decimalService = inject(DecimalService);

    startDate = signal(this.dateService.getStartOfYear());
    endDate = signal(this.dateService.getCurrentDate());
    selectedProduct = signal<Products | null>(null);

    productHistory = signal([]);
    productHistoryLoading = signal(false);

    searchProductHistory() {
        this.productHistoryLoading.set(true);
        let criteria = {
            startDate: this.dateService.formatDate(
                this.startDate(),
                'YYYY-MM-DD'
            ),
            endDate: this.dateService.formatDate(this.endDate(), 'YYYY-MM-DD'),
            product_id: this.selectedProduct().product_id,
        };

        this.http
            .post(`${this.api.host}/reports/product-history`, criteria)
            .subscribe({
                next: (res: any) => {
                    this.productHistoryLoading.set(false);
                    this.productHistory.set(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.productHistoryLoading.set(false);
                    this.notificationService.showError(error.error, 'home');
                },
            });
    }

    productHistoryTotals = computed(() => {
        return this.productHistory().reduce(
            (total, record) => {
                switch (record.transaction_type) {
                    case 'Sale':
                        if (record.include_vat) {
                            total.totalSellVAT = this.decimalService.add(
                                total.totalSellVAT,
                                record.quantity * record.unit_price
                            );
                            total.totalQuantitySellVAT += record.quantity;
                        } else {
                            total.totalSell = this.decimalService.add(
                                total.totalSell,
                                record.quantity * record.unit_price
                            );
                            total.totalQuantitySell += record.quantity;
                        }
                        break;

                    case 'Return':
                        if (record.include_vat) {
                            total.totalReturnVAT = this.decimalService.add(
                                total.totalReturnVAT,
                                record.quantity * record.unit_price
                            );
                            total.totalQuantityReturnVAT += record.quantity;
                        } else {
                            total.totalReturn = this.decimalService.add(
                                total.totalReturn,
                                record.quantity * record.unit_price
                            );
                            total.totalQuantityReturn += record.quantity;
                        }
                        break;

                    case 'Purchase':
                        if (record.include_vat) {
                            total.totalPurchaseVAT = this.decimalService.add(
                                total.totalPurchaseVAT,
                                record.quantity * record.unit_price
                            );
                            total.totalQuantityPurchasesVAT += record.quantity;
                        } else {
                            total.totalPurchase = this.decimalService.add(
                                total.totalPurchase,
                                record.quantity * record.unit_price
                            );
                            total.totalQuantityPurchases += record.quantity;
                        }
                        break;

                    case 'ADD':
                        total.totalQuantityAdd += record.quantity;
                        break;

                    case 'REMOVE':
                        total.totalQuantityRemove += record.quantity;
                        break;
                }
                return total;
            },
            {
                totalQuantityAdd: 0,
                totalQuantityRemove: 0,
                totalSell: 0,
                totalQuantitySell: 0,
                totalSellVAT: 0,
                totalQuantitySellVAT: 0,
                totalReturn: 0,
                totalQuantityReturn: 0,
                totalReturnVAT: 0,
                totalQuantityReturnVAT: 0,
                totalPurchase: 0,
                totalQuantityPurchases: 0,
                totalPurchaseVAT: 0,
                totalQuantityPurchasesVAT: 0,
            }
        );
    });
}
