import { Component, inject, computed } from '@angular/core';
import { ReportsService } from '../reports.service';

@Component({
    selector: 'customers-totals',
    templateUrl: './customers-totals.component.html',
    styleUrl: './customers-totals.component.scss',
})
export class CustomersTotalsComponent {
    readonly reportsService = inject(ReportsService);

    customersTotalPurchases = this.reportsService.customersTotalPurchases;

    readonly totals = computed(() => {
        const data = this.customersTotalPurchases();

        const base = data.reduce(
            (acc, record) => {
                const totalSales = Number(record.total_sales) || 0;
                const totalCost = Number(record.total_cost) || 0;
                const totalReturns = Number(record.total_returns) || 0;
                const totalReturnsCost = Number(record.total_returns_cost) || 0;

                acc.totalSales += totalSales;
                acc.totalCost += totalCost;
                acc.totalReturns += totalReturns;
                acc.totalReturnsCost += totalReturnsCost;

                return acc;
            },
            {
                totalSales: 0,
                totalCost: 0,
                totalReturns: 0,
                totalReturnsCost: 0,
            },
        );

        const grossProfit = base.totalSales - base.totalCost;

        const netSalesAfterReturns = base.totalSales - base.totalReturns;

        const netProfit =
            base.totalSales -
            base.totalReturns -
            (base.totalCost - base.totalReturnsCost);

        return {
            ...base,
            grossProfit,
            netSalesAfterReturns,
            netProfit,
        };
    });
}
