import { Component, OnDestroy, OnInit } from '@angular/core';
import { ReportsService } from '../reports.service';
import { Subscription } from 'rxjs';
import { Message } from 'primeng/api';

import * as moment from 'moment';

@Component({
    selector: 'app-reports-home',
    templateUrl: './reports-home.component.html',
    styleUrls: ['./reports-home.component.scss'],
})
export class ReportsHomeComponent implements OnInit, OnDestroy {
    constructor(private reportsService: ReportsService) { }

    subscriptions: Subscription = new Subscription();
    totalSales;
    // inventoryValue;
    payables;
    receivables;
    customersStatus = [];
    SuppliersStatus = [];

    emptyReportMessage: Message[];

    ngOnInit(): void {
        this.reportsService.init_reports();
        this.emptyReportMessage = [
            { severity: 'info', detail: 'No reports for this section!' },
        ];
        this.subscriptions.add(
            this.reportsService.totalSales.subscribe((res) => {
                this.totalSales = res;
            })
        );
        // this.subscriptions.add(
        //     this.reportsService.inventoryValue.subscribe(
        //         (res) => (this.inventoryValue = res)
        //     )
        // );
        this.subscriptions.add(
            this.reportsService.payables.subscribe(
                (res) => (this.payables = res)
            )
        );
        this.subscriptions.add(
            this.reportsService.receivables.subscribe(
                (res) => (this.receivables = res)
            )
        );
        // this.subscriptions.add(
        //     this.reportsService.totalSalesRevenue.subscribe(
        //         (res) => (this.salesRevenue = res)
        //     )
        // );
        this.subscriptions.add(
            this.reportsService.customersStatus.subscribe(
                (res) => (this.customersStatus = res)
            )
        );
        this.subscriptions.add(
            this.reportsService.suppliersStatus.subscribe(
                (res) => (this.SuppliersStatus = res)
            )
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }


}
