import { inject, Injectable, signal } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { BehaviorSubject, finalize } from 'rxjs';
import { NotificationsService } from 'src/app/_services/notifications.service';
import { ApiService } from '../_services/api.service';

import * as moment from 'moment';
import { DateService } from '../_services/date.service';
import { BalanceSheet } from '../core/interfaces/balance-sheet.interface';

@Injectable({
    providedIn: 'root',
})
export class ReportsService {
    constructor(
        private http: HttpClient,
        private notificationService: NotificationsService,
        private api: ApiService,
    ) {
        // this.init_reports();
    }

    readonly dateService = inject(DateService);

    private host = this.api.host;

    startDate = new BehaviorSubject(
        moment().clone().startOf('month').format('YYYY-MM-DD'),
    );
    endDate = new BehaviorSubject(moment().format('YYYY-MM-DD'));

    topCategories = new BehaviorSubject([]);
    topItems = new BehaviorSubject([]);
    totalSales = new BehaviorSubject({});
    inventoryValue = new BehaviorSubject({});
    costOfGodsSold = new BehaviorSubject({});
    totalSalesRevenue = new BehaviorSubject({});
    payables = new BehaviorSubject([]);
    receivables = new BehaviorSubject([]);
    customersTotalPurchases = signal([]);
    customersPaymentsTotals = new BehaviorSubject([]);
    suppliersPurchasesTotals = new BehaviorSubject([]);
    suppliersPaymentsTotals = new BehaviorSubject([]);
    customersStatus = new BehaviorSubject([]);
    suppliersStatus = new BehaviorSubject([]);

    trialBalance = new BehaviorSubject([]);
    AuxilaryDetails = new BehaviorSubject([]);
    trialBalanceLoading = new BehaviorSubject<boolean>(false);

    generalLedgerTotals = new BehaviorSubject([]);
    generalLedger = new BehaviorSubject([]);

    selectedPartnerAccount = new BehaviorSubject(null);
    selectedLedgerAccount = signal(null);
    accountLedger = new BehaviorSubject([]);
    balanceSheet = signal<BalanceSheet | null>(null);
    loadingBalanceSheet = signal(false);

    selectedAccountForStatement = new BehaviorSubject(null);
    statementOfAccounts = new BehaviorSubject([]);

    currencyOptions = new BehaviorSubject([
        { label: 'USD', value: 'USD' },
        { label: 'L.L', value: 'LBP' },
    ]);
    currencyValue = new BehaviorSubject<string>('USD');

    init_reports() {
        this.getTopCategories();
        this.getTopItems();

        this.getInventoryValue();

        // this.getTrialBalance();
        this.getGeneralLedgerTotals();
        this.getGeneralLedger();
        // this.getAuxilaryDetails();
        this.getAccountLedger();
        // the balance sheet has its own "as of" date, so it is not part of the
        // shared start/end date refresh - the page fetches it itself
        this.getStatementOfAccounts();
        this.getCustomersTotalPurchases();
        this.getRevenue();
        this.getReturns();
    }

    getTopCategories() {
        this.http
            .get(
                `${this.host}/reports/categories/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.topCategories.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getTopItems(customer_id = null) {
        this.http
            .get(
                `${this.host}/reports/items/${this.startDate.value}&${this.endDate.value}&${customer_id}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.topItems.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getTotalSales() {
        this.http
            .get(
                `${this.host}/reports/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.totalSales.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getInventoryValue() {
        this.http.get(`${this.host}/reports/inventory_value`).subscribe({
            next: (res: any) => {
                this.inventoryValue.next(res);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'reports');
            },
        });
    }

    getCostOfGoodsSold() {
        this.http
            .get(
                `${this.host}/reports/cost_of_goods_sold/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.costOfGodsSold.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getSalesRevenue() {
        this.http
            .get(
                `${this.host}/reports/total_sales_revenue/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.totalSalesRevenue.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getPayables() {
        this.http.get(`${this.host}/reports/payables`).subscribe({
            next: (res: any) => {
                this.payables.next(res);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'reports');
            },
        });
    }

    getReceivables() {
        this.http.get(`${this.host}/reports/receivables`).subscribe({
            next: (res: any) => {
                this.receivables.next(res);
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'reports');
            },
        });
    }

    getCustomersTotalPurchases() {
        this.http
            .get(
                `${this.host}/reports/customers/purchases/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.customersTotalPurchases.set(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getCustomersPaymentsTotals() {
        this.http
            .get(
                `${this.host}/reports/customers/payments/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.customersPaymentsTotals.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getSuppliersPurchasesTotals() {
        this.http
            .get(
                `${this.host}/reports/suppliers/purchases/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.suppliersPurchasesTotals.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getSuppliersPaymentsTotals() {
        this.http
            .get(
                `${this.host}/reports/suppliers/payments/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.suppliersPaymentsTotals.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getCustomersStatus() {
        this.http
            .get(
                `${this.host}/reports/customers/status/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.customersStatus.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }
    getSuppliersStatus() {
        this.http
            .get(
                `${this.host}/reports/suppliers/status/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.suppliersStatus.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    // trial balance
    getTrialBalance(options) {
        this.trialBalanceLoading.next(true);
        this.http
            .post(`${this.host}/reports/trial_balance`, options)
            .subscribe({
                next: (res: any) => {
                    this.trialBalance.next(res);
                    this.trialBalanceLoading.next(false);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                    this.trialBalanceLoading.next(false);
                },
            });
    }

    // get trial balance auxiliary details
    auxiliaryStatementsLoading = new BehaviorSubject(false);
    getAuxilaryDetails(options) {
        this.auxiliaryStatementsLoading.next(true);
        this.http
            .get(
                `${this.host}/reports/trial_balance_auxilary/${options.startDate}&${options.endDate}&${options.showZero}&${options.onlyAuxiliary}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.AuxilaryDetails.next(res);
                    this.auxiliaryStatementsLoading.next(false);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                    this.auxiliaryStatementsLoading.next(false);
                },
            });
    }

    getGeneralLedgerTotals() {
        this.http
            .get(
                `${this.host}/reports/general_ledger_totals/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.generalLedgerTotals.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getGeneralLedger() {
        this.http
            .get(
                `${this.host}/reports/general_ledger/${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.generalLedger.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    getAccountLedger() {
        if (!this.selectedPartnerAccount.value) return;
        let selectedAccount = this.selectedPartnerAccount.value;
        this.http
            .get(
                `${this.host}/auxiliary/account_ledger/${
                    selectedAccount.account_id
                }&${this.selectedLedgerAccount()}&${this.startDate.value}&${
                    this.endDate.value
                }`,
            )
            .subscribe({
                next: (res: any) => {
                    this.accountLedger.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    // get statement of accounts
    getStatementOfAccounts() {
        if (!this.selectedAccountForStatement.value) return;
        let selectedAccount = this.selectedAccountForStatement.value;
        this.http
            .get(
                `${this.host}/reports/statement/${selectedAccount.id}&${this.startDate.value}&${this.endDate.value}`,
            )
            .subscribe({
                next: (res: any) => {
                    this.statementOfAccounts.next(res);
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(
                        error.error,
                        'reports',
                    );
                },
            });
    }

    /**
     * The balance sheet is a point-in-time statement: it takes a single "as of"
     * date and the server accumulates every posted entry up to it.
     */
    getBalanceSheet(asOf: string, showZero = false) {
        this.loadingBalanceSheet.set(true);
        const date = this.dateService.formatDate(asOf, 'YYYY-MM-DD');
        this.api
            .get<BalanceSheet>(`reports/balance_sheet/${date}&${showZero}`)
            .pipe(
                finalize(() => {
                    this.loadingBalanceSheet.set(false);
                }),
            )
            .subscribe({
                next: (data) => {
                    this.balanceSheet.set(data);
                },
                // ApiService.handleError already reports the failure
                error: () => {
                    this.balanceSheet.set(null);
                },
            });
    }

    // new reports
    selectedLinkId = signal<number | null>(null);

    revenue = signal<any>({});
    loadingRevenue = signal(false);

    // get revenue
    getRevenue(
        startDate: string = this.startDate.value,
        endDate: string = this.endDate.value,
    ) {
        this.loadingRevenue.set(true);
        startDate = this.dateService.formatDate(startDate, 'YYYY-MM-DD');
        endDate = this.dateService.formatDate(endDate, 'YYYY-MM-DD');
        this.api
            .get(
                `reports/revenue/${startDate}&${endDate}&${this.selectedLinkId()}`,
            )
            .pipe(
                finalize(() => {
                    this.loadingRevenue.set(false);
                }),
            )
            .subscribe({
                next: (data: any) => {
                    this.revenue.set(data);
                    console.log(data);
                },
            });
    }

    // returns
    returns = signal<any>({});
    loadingReturns = signal(false);

    // get revenue
    getReturns(
        startDate: string = this.startDate.value,
        endDate: string = this.endDate.value,
    ) {
        this.loadingReturns.set(true);
        startDate = this.dateService.formatDate(startDate, 'YYYY-MM-DD');
        endDate = this.dateService.formatDate(endDate, 'YYYY-MM-DD');
        this.api
            .get(
                `reports/returns/${startDate}&${endDate}&${this.selectedLinkId()}`,
            )
            .pipe(
                finalize(() => {
                    this.loadingReturns.set(false);
                }),
            )
            .subscribe({
                next: (data: any) => {
                    this.returns.set(data);
                    console.log(data);
                },
            });
    }
}
