import { Component, OnInit, OnDestroy } from '@angular/core';
import { ReportsService } from '../reports.service';
import { Subscription } from 'rxjs';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';
import { DateService } from 'src/app/_services/date.service';
import { PrintService } from 'src/app/print.service';
import { AccountingService } from 'src/app/accounting/accounting.service';

@Component({
    selector: 'app-statements',
    templateUrl: './statements.component.html',
    styleUrl: './statements.component.scss',
})
export class StatementsComponent implements OnInit, OnDestroy {
    constructor(
        private reportsService: ReportsService,
        private auxiliaryService: AuxiliaryService,
        private dateService: DateService,
        private printService: PrintService,
        private accountingService: AccountingService
    ) {}
    subscriptions = new Subscription();
    accounts;
    selectedAccount;
    selectedLedgerAccount = this.reportsService.selectedLedgerAccount;
    data;
    startDate;
    endDate;
    balances = [];
    balances_lbp = [];
    show_dollar = true;

    currencyOptions;
    currencyValue;
    chartOfAccounts;

    ngOnInit() {
        this.subscriptions.add(
            this.accountingService.chartOfAccounts.subscribe((res) => {
                this.chartOfAccounts = res;
            })
        );
        this.subscriptions.add(
            this.reportsService.currencyOptions.subscribe((res) => {
                this.currencyOptions = res;
            })
        );
        this.subscriptions.add(
            this.reportsService.currencyValue.subscribe((res) => {
                this.currencyValue = res;
            })
        );

        this.subscriptions.add(
            this.auxiliaryService.accounts.subscribe((accounts) => {
                this.accounts = accounts;
            })
        );
        this.subscriptions.add(
            this.reportsService.accountLedger.subscribe((data) => {
                this.data = data;
                if (data.length > 0) {
                    this.balances = [];
                    this.balances_lbp = [];
                    this.balances[0] = parseFloat(data[0].balance);
                    this.balances_lbp[0] =
                        parseFloat(data[0].debit_lbp) -
                        parseFloat(data[0].credit_lbp);
                    for (let i = 1; i < data.length; i++) {
                        this.balances[i] =
                            this.balances[i - 1] +
                            parseFloat(data[i].debit) -
                            parseFloat(data[i].credit);
                        this.balances_lbp[i] =
                            this.balances_lbp[i - 1] +
                            parseFloat(data[i].debit_lbp) -
                            parseFloat(data[i].credit_lbp);
                    }
                } else {
                    this.balances = [];
                    this.balances_lbp = [];
                }
            })
        );
        this.subscriptions.add(
            this.reportsService.startDate.subscribe((res) => {
                this.startDate = res;
            })
        );
        this.subscriptions.add(
            this.reportsService.endDate.subscribe((res) => {
                this.endDate = res;
            })
        );
        this.subscriptions.add(
            this.reportsService.selectedPartnerAccount.subscribe((res) => {
                this.selectedAccount = res;
            })
        );
    }
    ngOnDestroy() {
        this.subscriptions.unsubscribe();
    }

    startDateChanged() {
        this.reportsService.startDate.next(
            this.dateService.formatDate(this.startDate)
        );
        this.reportsService.init_reports();
    }

    endDateChanged() {
        this.reportsService.endDate.next(
            this.dateService.formatDate(this.endDate)
        );
        this.reportsService.init_reports();
    }

    accountChanged() {
        if (this.selectedAccount) {
            this.reportsService.selectedPartnerAccount.next(
                this.selectedAccount
            );
            this.reportsService.init_reports();
        } else {
            this.reportsService.selectedPartnerAccount.next(null);
            this.reportsService.accountLedger.next([]);
        }
    }

    changeCurrency(event) {
        this.reportsService.currencyValue.next(event.value);
    }

    printStatement() {
        let dataToPrint = [
            this.data,
            this.balances,
            this.balances_lbp,
            this.startDate,
            this.endDate,
            this.selectedAccount,
        ];
        this.printService.printStatement(dataToPrint);
    }
}
